-- Church programme: the SCC annual calendar (public; board meetings for leaders only) and the
-- Germiston Sub-Region year planner (members only). Admins can add more in Admin → Church programme.
CREATE TABLE IF NOT EXISTS church_programme (
  id          TEXT PRIMARY KEY,
  source      TEXT NOT NULL DEFAULT 'admin',      -- scc | germiston | admin
  audience    TEXT NOT NULL DEFAULT 'public',     -- public | members | leaders
  start_date  TEXT NOT NULL,                      -- YYYY-MM-DD
  end_date    TEXT,
  time_label  TEXT,
  title       TEXT NOT NULL,
  department  TEXT,
  venue       TEXT,
  notes       TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX IF NOT EXISTS idx_programme_date ON church_programme (start_date, audience);
